# Re-score one actual decision on identical candidates and identical inner set, 32 vs 1024 samples.
class ReviewStop(Exception): pass
mc_rows=[]; high_eps_cache={}; snapshots={}
def mc_hook(it,grp,net,kg_group,Z,Xi,eps,w,ww,cv,kg):
    if it!=1: raise ReviewStop()
    if it not in high_eps_cache:
        extra=pol.eps_for(len(Xi),1024-pol.S_ACQ,880001)
        high_eps_cache[it]={n:torch.cat([eps[n],extra[n]],-1) for n in ba.ORDER}
        snapshots[it]={'Xi':Xi.clone(),'eps_low':eps,'eps_high':high_eps_cache[it], 'groups':{}}
    start=time.time()
    hi=net.kg(kg_group,Z,Xi,high_eps_cache[it],w,ww,chunk=1).clamp_min(0)
    snapshots[it]['groups'][grp]={'Z':Z.clone(),'w':w.clone(),'ww':ww.clone(),'cost':cv.clone(),'kg_low':kg.clone(),'kg_high':hi.clone()}
    mc_rows.append({'iteration':it,'group':grp,'n_candidates':len(Z),'n_inner':len(Xi),'best_index32':int((kg/cv).argmax()),'best_index1024':int((hi/cv).argmax()),'max_ratio32':float((kg/cv).max()),'max_ratio1024':float((hi/cv).max()),'max_abs_kg_difference':float((hi-kg).abs().max()),'kg32':kg.tolist(),'kg1024':hi.tolist(),'costs':cv.tolist(),'seconds1024':time.time()-start})
old_hook=pol.KG_HOOK; pol.KG_HOOK=mc_hook
try:
    torch.manual_seed(0)
    pol.run_pkgfn(ba.AlloyTruth(),0,100_000)
except ReviewStop:
    pass
finally:
    pol.KG_HOOK=old_hook
lo=max(mc_rows,key=lambda r:r['max_ratio32']); hi=max(mc_rows,key=lambda r:r['max_ratio1024'])
record('mc_rescore',{'seed':0,'iteration':1,'settings':{'low':32,'high':1024,'N_CAND':pol.N_CAND,'N_POOL':pol.N_POOL},'winner32':[lo['group'],lo['best_index32'],lo['max_ratio32']],'winner1024':[hi['group'],hi['best_index1024'],hi['max_ratio1024']],'scores':mc_rows})
torch.save(snapshots,OUT/'mc_rescore_snapshot.pt')
'''
